<div class="page-head"><div><h1>Pick, pack, dispatch</h1><p class="sub"><?= esc(wh_name($wh)) ?></p></div><div class="actions"><a class="btn secondary" href="<?= site_url('waves') ?>">Wave picking</a><a class="btn secondary" href="<?= site_url('orders?status=to_pick') ?>">Orders to pick</a><?php if (can('fleet.manage') && \App\Libraries\Platform\Modules::on('fleet')): ?><a class="btn secondary" href="<?= site_url('fleet/trips/new') ?>">Plan a trip</a><?php endif ?></div></div>
<div class="pill-filter"><?php foreach (['open' => 'Being prepared', 'allocated' => 'To pick', 'picked' => 'To pack', 'packed' => 'To dispatch', 'dispatched' => 'On the way', 'delivered' => 'Delivered', 'failed' => 'Failed', 'all' => 'All'] as $k => $l): ?><a href="<?= site_url('shipments?status=' . $k) ?>" class="<?= $st === $k ? 'on' : '' ?>"><?= $l ?></a><?php endforeach ?></div>
